\usepgfplotslibrary{colormaps}
\pgfplotsset{compat=1.18}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    view={45}{20},
    xlabel={$x$},
    ylabel={$y$},
    zlabel={$z$},
    title={Hyperbolic Cylinder: $xy = 1$},
    xlabel style={font=\bfseries},
    ylabel style={font=\bfseries},
    zlabel style={font=\bfseries},
    title style={font=\bfseries\large},
    colormap/name=viridis,
    grid=major,
    width=14cm,
    height=10cm
]
% First branch (x > 0, y > 0)
\addplot3[surf, shader=flat corner, samples=30, samples y=15, domain=0.2:3, z domain=-3:3, opacity=0.7] 
    (x, {1/x}, z);

% Second branch (x < 0, y < 0)
\addplot3[surf, shader=flat corner, samples=30, samples y=15, domain=-3:-0.2, z domain=-3:3, opacity=0.7] 
    (x, {1/x}, z);

\end{axis}
\end{tikzpicture}
\end{document}

